NEW_FILES = {'tests/test_shelf_stock_vault.py': '"""1.142.0 -- a bank vault\'s rack carries the money (the factory\'s roadmap 321).\n\nThe walker, of the bank\'s vault: "we need to make the cash! in the vault room!". The vault held a cash cart, two\nsafes and a count table with a few bundles on it, each bundle a note\'s size and invisible at a room\'s distance.\n`shelving`\'s ``vault`` stock puts brick rows -- ten straps of a hundred notes, banded by denomination -- and deposit\nbags on a vault rack\'s shelves (`_shelf_stock.plan_vault_shelf`). These check the rules the planner keeps: nothing\noverhangs, nothing shares a plane with anything (a band and its own row included), a stacked row stands off the one\nunder it, every band wraps its own row, the colours read, and the back office\'s stock is what it was.\n"""\nfrom __future__ import annotations\n\nimport itertools\nimport json\nimport os\nimport random\n\nimport pytest\n\nfrom zoo_keeper.core import genome, skins\nfrom zoo_keeper.recipes import _shelf_stock as ss\n\n_ZOO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n_GENOME = os.path.join(_ZOO, "zoo_keeper", "genome", "species", "shelving.json")\n\n#: (x0, x1, y_front, y_back, z0, clear): the spans `shelving.build` gives Deli Counter\'s two `shelf_cash` sizes\'\n#: bays (1.8 x 0.5 x 1.9 and 1.2 x 0.5 x 1.8, four shelves), a deep 2.4 m bay, and two too small for a brick\nSPANS = [\n    (-0.85, 0.85, -0.24, 0.226, 0.038, 0.588),\n    (-0.55, 0.55, -0.24, 0.226, 0.643, 0.555),\n    (-1.15, 1.15, -0.288, 0.276, 0.038, 0.655),\n    (-0.95, 0.95, -0.216, 0.201, 0.038, 0.549),\n]\nSEEDS = range(40)\n\n\ndef _plan(seed, span):\n    return ss.plan_vault_shelf(random.Random(seed), *span)\n\n\ndef _overlap(a0, a1, b0, b1):\n    return min(a1, b1) - max(a0, b0)\n\n\ndef _rows(items):\n    """[(row, band)]: `_bricks` writes a row and then its band."""\n    out = []\n    for i, it in enumerate(items):\n        if it["finish"] == ss.NOTES:\n            out.append((it, items[i + 1]))\n    return out\n\n\n@pytest.mark.parametrize("span", SPANS)\ndef test_nothing_overhangs(span):\n    x0, x1, yf, yb, z0, clear = span\n    for seed in SEEDS:\n        for it in _plan(seed, span):\n            lo, hi = it["min"], it["max"]\n            assert lo[0] >= x0 + ss.EDGE - 1e-9 and hi[0] <= x1 - ss.EDGE + 1e-9, it\n            assert lo[1] >= yf + ss.EDGE - 1e-9 and hi[1] <= yb - ss.BACK_GAP + 1e-9, it\n            assert hi[2] <= z0 + clear - ss.HEADROOM + 1e-9, it\n            assert lo[2] >= z0 - ss.SINK - 1e-9, it\n\n\n@pytest.mark.parametrize("span", SPANS)\ndef test_no_two_faces_share_a_plane(span):\n    """`test_shelf_stock`\'s rule, every pair of items and each against its board, and stricter than that module\'s\n    stock needs: a band overlaps its own row by design, so its faces are held off the row\'s too."""\n    tol = 0.002\n    x0, x1, yf, yb, z0, clear = span\n    board = {"min": (x0 - 1, yf - 1, z0 - 0.035), "max": (x1 + 1, yb + 1, z0)}\n    for seed in SEEDS[:15]:\n        items = _plan(seed, span)\n        for a, b in itertools.combinations(items + [board], 2):\n            for k in range(3):\n                o = [m for m in range(3) if m != k]\n                if (_overlap(a["min"][o[0]], a["max"][o[0]], b["min"][o[0]], b["max"][o[0]]) <= 1e-6\n                        or _overlap(a["min"][o[1]], a["max"][o[1]], b["min"][o[1]], b["max"][o[1]]) <= 1e-6):\n                    continue\n                for fa in (a["min"][k], a["max"][k]):\n                    for fb in (b["min"][k], b["max"][k]):\n                        assert abs(fa - fb) >= tol, (seed, k, a, b)\n\n\n@pytest.mark.parametrize("span", SPANS)\ndef test_a_row_is_a_brick_long_and_bricks_deep_and_its_band_wraps_it(span):\n    for seed in SEEDS:\n        for row, band in _rows(_plan(seed, span)):\n            assert band["finish"].startswith("band_"), band\n            lo, hi = row["min"], row["max"]\n            assert hi[0] - lo[0] == pytest.approx(ss.BRICK_X)\n            deep = (hi[1] - lo[1]) / ss.BRICK_Y\n            assert deep == pytest.approx(round(deep)) and round(deep) >= 1\n            assert hi[2] - lo[2] == pytest.approx(ss.BRICK_H)\n            # the band: across the row\'s middle, proud of its front, back and top, its foot inside the row\n            assert (band["min"][0] + band["max"][0]) / 2 == pytest.approx((lo[0] + hi[0]) / 2)\n            assert band["max"][0] - band["min"][0] == pytest.approx(ss.BAND_W)\n            assert band["min"][1] == pytest.approx(lo[1] - ss.BAND_PROUD)\n            assert band["max"][1] == pytest.approx(hi[1] + ss.BAND_PROUD)\n            assert band["max"][2] == pytest.approx(hi[2] + ss.BAND_PROUD)\n            assert lo[2] < band["min"][2] < hi[2]\n\n\n@pytest.mark.parametrize("span", SPANS)\ndef test_rows_side_by_side_never_meet_and_a_stacked_row_stands_off_the_one_under_it(span):\n    for seed in SEEDS:\n        rows = [r for r, _b in _rows(_plan(seed, span))]\n        bags = [it for it in _plan(seed, span) if it["finish"] in ss.BAGS]\n        for a, b in itertools.combinations(rows + bags, 2):\n            ov = [_overlap(a["min"][k], a["max"][k], b["min"][k], b["max"][k]) for k in range(3)]\n            if min(ov) <= 0:\n                continue\n            lower, upper = (a, b) if a["min"][2] < b["min"][2] else (b, a)\n            assert abs(upper["min"][2] - (lower["max"][2] - ss.SINK)) < 1e-9, (seed, a, b)\n            for k in (0, 1):\n                assert abs(upper["min"][k] - lower["min"][k]) >= ss.STACK_STEP - 1e-9, (seed, a, b)\n                assert abs(upper["max"][k] - lower["max"][k]) >= ss.STACK_STEP - 1e-9, (seed, a, b)\n\n\ndef test_a_vault_shelf_is_money():\n    """The complaint was a vault with no money in it: a Deli Counter rack\'s bay is mostly brick rows."""\n    x0, x1 = SPANS[0][0], SPANS[0][1]\n    for seed in SEEDS:\n        items = _plan(seed, SPANS[0])\n        rows = [it for it in items if it["finish"] == ss.NOTES]\n        assert len(rows) >= 6, seed\n        base = [it for it in items if abs(it["min"][2] - (SPANS[0][4] - ss.SINK)) < 1e-9]\n        used = sum(it["max"][0] - it["min"][0] for it in base)\n        assert used / (x1 - x0) >= 0.4, (seed, used)\n    bands = {it["finish"] for s in SEEDS for it in _plan(s, SPANS[0]) if it["finish"].startswith("band_")}\n    assert bands == {b for b, _w in ss.BANDS}\n\n\ndef test_same_seed_same_shelf_and_seeds_differ():\n    assert _plan(7, SPANS[0]) == _plan(7, SPANS[0])\n    assert len({json.dumps(_plan(s, SPANS[0])) for s in SEEDS}) == len(SEEDS)\n\n\ndef test_a_shelf_too_low_or_too_shallow_stays_empty():\n    assert ss.plan_vault_shelf(random.Random(1), -0.5, 0.5, -0.2, 0.2, 0.0, 0.05) == []\n    assert ss.plan_vault_shelf(random.Random(1), -0.5, 0.5, -0.03, 0.03, 0.0, 0.5) == []\n\n\ndef _lum(c):\n    return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]\n\n\ndef _ratio(a, b):\n    hi, lo = sorted((_lum(a), _lum(b)), reverse=True)\n    return (hi + 0.05) / (lo + 0.05)\n\n\ndef test_the_money_reads():\n    """`test_shelf_stock`\'s 1.4 against every shelving style\'s board and frame for the notes and the bags, and the\n    same 1.4 between each band and the notes it is wrapped round: the band is how a rack reads as money."""\n    g = json.load(open(_GENOME, encoding="utf-8"))\n    greys = []\n    for st in g["styles"].values():\n        greys += [st["color"], [v * 0.7 for v in st["color"]]]\n    for finish in (ss.NOTES,) + ss.BAGS:\n        for grey in greys:\n            assert _ratio(ss.VAULT_PALETTE[finish], grey) >= 1.4, (finish, grey)\n    for band, _w in ss.BANDS:\n        assert _ratio(ss.VAULT_PALETTE[band], ss.VAULT_PALETTE[ss.NOTES]) >= 1.4, band\n    assert set(ss.VAULT_PALETTE) == {ss.NOTES} | {b for b, _w in ss.BANDS} | set(ss.BAGS)\n    assert ss.VAULT_KIND in skins.KNOWN_KINDS\n\n\ndef test_shelving_honours_the_vault_stock_and_nothing_else_moves():\n    from zoo_keeper.core import kit\n    g = genome.load_species("shelving")\n    assert g["params"]["stock"] == ["none", "vault"]\n    slot = {"slot_id": "s", "role": "shelving", "species": "shelving", "stock": "vault"}\n    dress, dropped = kit.honour_dressing(slot, "shelving")\n    assert dress["stock"] == "vault" and dropped == []\n    # an unstocked rack asks for nothing, and a flavour shelving has no rule for drops all of it\n    assert kit.honour_dressing({"slot_id": "s"}, "shelving") == ({"form": None, "stock": None, "variant": None}, [])\n    assert kit.honour_dressing(dict(slot, stock="bar"), "shelving")[1]\n    # the back office\'s planner is untouched: the same seed draws the same shelf it always did\n    assert ss.plan_shelf(random.Random(3), -0.95, 0.95, -0.192, 0.172, 0.038, 0.549) == \\\n        ss.plan_shelf(random.Random(3), -0.95, 0.95, -0.192, 0.172, 0.038, 0.549)\n', 'tests/test_vault_money_and_frames.py': '"""1.142.0 -- the bank\'s three reads-wrong (the factory\'s docs/findings/bank_interior/, frame 18), built.\n\n* A glass wall\'s storefront frames in aluminium (`arch.SF_FRAME_FOR`): the bank\'s mullions and the band over its glass\n  drew in the opaque curtain-wall skin and read as dark brown bars. A brick shop front\'s frame keeps its brick.\n* A vault rack\'s money (`shelving`\'s ``vault`` stock) is one material whatever its denominations, and the rack passes\n  its budget at Deli Counter\'s widest.\n\nThe deposit wall\'s painted steel is a genome change, checked in `test_safe_deposit_boxes.py`. Run the bpy half in\nBlender:\n\n    blender -b --factory-startup --python-expr "import sys, pytest; sys.path.insert(0, \'.\'); print(\'rc\', int(pytest.main([\'-q\', \'-p\', \'no:cacheprovider\', \'tests/test_vault_money_and_frames.py\'])))"\n"""\nfrom __future__ import annotations\n\nimport pytest\n\nfrom zoo_keeper.core import arch, kit\n\n\ndef test_a_glass_wall_is_what_frames_in_aluminium():\n    assert arch.SF_FRAME_FOR == {"glass", "glass_facade"}\n    assert arch.SF_FRAME_KIND == "metal_painted"          # a building piece: bare steel mirrors the dark room\n    assert min(arch.SF_FRAME_RGB) >= 0.6                  # clear anodised, not the bronze it read as\n\n\ndef _clear():\n    import bpy\n    for o in list(bpy.data.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n\n\ndef _storefront(tmp_path, material):\n    import bpy\n    from zoo_keeper.bpylayer import build as B\n    _clear()\n    slot = {"slot_id": "s", "role": "wall", "size_mod": "full", "style": 2, "material": material,\n            "glazing": "storefront", "fit": {"dims": [2.0, 0.3, 3.9], "pivot": "center", "openings": [],\n                                             "collision": "convex"}}\n    m = kit.plan_kit({"building_id": "t", "slots": [slot]}, theme="delco_1997", style=1)["modules"][0]\n    res = B.build_module(m, str(tmp_path / material), theme="delco_1997", style=1, options={"save_blend": False})\n    return res, {o.name: o.data.materials[0].name for o in bpy.data.objects\n                 if o.type == "MESH" and o.data.materials and not o.name.endswith("-colonly")}\n\n\ndef test_bpy_a_glass_storefront_frames_in_aluminium_and_a_brick_one_in_brick(tmp_path):\n    pytest.importorskip("bpy")\n    res, mats = _storefront(tmp_path, "glass")\n    assert res["report"]["status"] == "pass", res["report"]["checks"]\n    frame = {n: m for n, m in mats.items() if any(k in n for k in ("Kick", "Header", "Mullion"))}\n    assert len(frame) >= 4, sorted(mats)\n    assert set(frame.values()) == {"M_Storefront_frame"}, frame\n    _res, mats = _storefront(tmp_path, "brick")\n    frame = {n: m for n, m in mats.items() if any(k in n for k in ("Kick", "Header", "Mullion"))}\n    assert frame and "M_Storefront_frame" not in frame.values(), frame\n\n\ndef _rack(tmp_path, dims, stock):\n    import bpy\n    from zoo_keeper.bpylayer import build as B\n    _clear()\n    slot = {"slot_id": "shelf_cash_0", "role": "prop", "size_mod": "full", "style": 1, "species": "shelving",\n            "fit": {"dims": list(dims), "pivot": "center"}}\n    if stock:\n        slot["stock"] = stock\n    m = kit.plan_kit({"building_id": "t", "slots": [slot]}, theme="delco", style=1)["modules"][0]\n    res = B.build_module(m, str(tmp_path / m["stem"]), theme="delco", style=1, options={"save_blend": False})\n    meshes = [o for o in bpy.data.objects if o.type == "MESH" and not o.name.endswith("-colonly")]\n    return m, res, meshes\n\n\n@pytest.mark.parametrize("dims", [(1.2, 0.5, 1.8), (1.8, 0.5, 1.9), (2.4, 0.6, 2.1)])\ndef test_bpy_a_vault_rack_is_money_on_one_material(tmp_path, dims):\n    pytest.importorskip("bpy")\n    m, res, meshes = _rack(tmp_path, dims, "vault")\n    assert "vault" in m["stem"], m["stem"]\n    assert res["report"]["status"] == "pass", res["report"]["checks"]\n    stock = [o for o in meshes if o.name.startswith("Shelf_Stock_")]\n    assert any(o.name == "Shelf_Stock_notes" for o in stock), sorted(o.name for o in meshes)\n    assert {s.material.name for o in stock for s in o.material_slots} == {"M_Shelf_vault_stock"}\n    # the frame\'s two and the money\'s one\n    assert len({s.material.name for o in meshes for s in o.material_slots}) == 3\n\n\ndef test_bpy_an_unstocked_rack_is_the_back_office_it_was(tmp_path):\n    pytest.importorskip("bpy")\n    m, res, meshes = _rack(tmp_path, (1.8, 0.5, 1.9), None)\n    assert "vault" not in m["stem"]\n    names = {o.name for o in meshes}\n    assert "Shelf_Stock_notes" not in names\n    assert any(s.material.name.startswith("M_Shelf_stock_") for o in meshes for s in o.material_slots)\n'}
CHANGELOG = '## [1.142.0] - the vault\'s money on its racks, a glass storefront\'s frame in aluminium, the deposit wall painted\n\nThe walker, of the bank after the interior pass: "add the lobby desks and fix those two first" -- the deposit wall\'s\nsteel reading dark and the storefront\'s mullions reading as dark stripes (the factory\'s\ndocs/findings/bank_interior/, frame 18) -- and then "we need to make the cash! in the vault room!". The vault held a\ncash cart, two safes and a count table with a few bundles on it, each bundle a note\'s size.\n\n### Added\n- **A bank vault\'s rack carries the money** (`shelving`\'s `stock` param, `none` or `vault`;\n  `_shelf_stock.plan_vault_shelf`).\n  - BRICKS, as a vault keeps them: ten straps of a hundred notes, 156 x 66 mm and 109 mm high, stacked flat in\n    rows a whole number of bricks deep, each row\'s band round its middle in the ABA\'s strap colour for its\n    denomination ($20 violet the most, $100 mustard, $50 brown, $10 yellow, $5 red, $1 blue), one denomination to\n    a block and now and then a column of another. A row is one box and its band one more: bricks lined up front to\n    back line their bands up.\n  - Deposit bags among them, navy, tan or clear, one to three in a pile (the walker\'s comp 10, "stacked deposit\n    bags"), and a gap now and then where a block went out.\n  - ALL OF IT ONE MATERIAL, `paper`, its colours in the `Wear` vertex colour: a loaded rack is the frame\'s two\n    materials and the money\'s one, where the back office\'s stock is a material a finish.\n  - A stacked row stands `BRICK_STAGGER` (4 mm) either side of its column\'s line, alternating, so no side shares a\n    plane with the row under it; a band stands 3 mm off its row\'s front, back and top and starts `BAND_FOOT`\n    (8.5 mm) over the row\'s base, clear of the row below and that row\'s band. The coplanar probe on the\n    1.8 x 0.5 x 1.9 rack: 2,228 triangles, 0 coincident pairs.\n  - `none`, the default, is the back office\'s stock as before: every existing rack\'s stem, planner and draws are\n    unchanged. Deli Counter\'s `shelf_cash` (0.286.0) asks for `vault` on a bank vault\'s walls.\n\n### Changed\n- **A glass wall\'s storefront frames in aluminium** (`arch.SF_FRAME_FOR`, `SF_FRAME_KIND`, `SF_FRAME_RGB`).\n  - A storefront\'s frame -- kick, header, mullions, jambs, rail and leaves -- builds in its wall\'s material. On a\n    brick or block front that is a material a frame can be made of; a `glass` wall\'s is `glass_facade`\n    (`dna.OPAQUE_FOR`), the opaque curtain-wall skin, and the three bank fronts Deli Counter 0.285.0 made storefronts\n    drew every mullion and the band over the glass in it: dark brown bars from inside.\n  - Those frames take clear anodised aluminium, `metal_painted` (0.66, 0.67, 0.69), one material\n    (`M_Storefront_frame`). Painted, not bare: a frame is a building piece lit by the bake, and bare steel at\n    metallic 0.9 mirrored the dark room on the vault door (the factory\'s roadmap, item 46).\n  - The brick and block fronts keep their frames in their walls\' materials. The module docstring has called every\n    storefront "aluminium" since 1.18.0; making the rest so would move every shop front in the library, and is the\n    walker\'s call, not this release\'s.\n- **The deposit wall is painted steel** (`safe_deposit_boxes`: `metal_painted`, or `laminate`; was `metal_bare`).\n  - A deposit wall is a building piece in Deli Counter\'s slots, lit by the bake. At metallic 0.9 it read near black\n    in the vault beside a cash cart of the same bare steel, which is a prop lit live. The vault door went painted in\n    0.86.0 for the same reading. The brass locks and number plates stay in the vertex colour.\n  - The styles\' steel is lighter, a mean of 0.54-0.65 where it was 0.45-0.53. A species offers one metal\n    (`test_no_species_is_both_painted_and_bare`), so `metal_bare` is no longer an option.\n- **`shelving`\'s budget is 5,000 triangles** (was 3,000): a vault rack\'s money at Deli Counter\'s 2.4 m bay draws up to\n  316 boxes, 3,792 triangles, the frame\'s on top. A regression detector, not a frame cost: the rack\'s draws are\n  three materials.\n\n### Tests\n- `tests/test_shelf_stock_vault.py` (new; fails on 1.141.0): nothing overhangs; no two faces share a plane, a band and\n  its own row included; a row is a brick long and whole bricks deep and its band wraps it; a stacked row stands off\n  the one under it; a Deli Counter bay is mostly money and draws every denomination; the colours read (notes and\n  bags against every shelving grey, every band against the notes); shelving honours `vault` and nothing else.\n- `tests/test_vault_money_and_frames.py` (new; fails on 1.141.0): a glass storefront\'s frame builds in\n  `M_Storefront_frame` and a brick one\'s does not; a vault rack builds its money on one material at three sizes,\n  within budget; an unstocked rack is the back office it was.\n- `tests/test_safe_deposit_boxes.py`: the wall is painted steel, its styles light.\n- `tests/test_material_options_closed.py`: `safe_deposit_boxes` moves from BARE to PAINTED.\n\n'
OLD_VERSION, NEW_VERSION = '1.141.0', '1.142.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
